using Microsoft.VisualStudio.TestTools.UnitTesting;
using Store;

namespace Store.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    // --- AddItem Tests ---

    [TestMethod]
    public void AddItem_SingleItem_NoException()
    {
        _cart.AddItem("SKU001", 1, 9.99m);
    }

    [TestMethod]
    public void AddItem_MultipleItems_NoException()
    {
        _cart.AddItem("SKU001", 2, 10.00m);
        _cart.AddItem("SKU002", 1, 5.50m);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_NoException()
    {
        _cart.AddItem("SKU001", 1, 10.00m);
        _cart.AddItem("SKU001", 3, 10.00m);
    }

    // --- RemoveItem Tests ---

    [TestMethod]
    public void RemoveItem_ExistingItem_NoException()
    {
        _cart.AddItem("SKU001", 1, 10.00m);
        _cart.RemoveItem("SKU001");
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_NoException()
    {
        _cart.RemoveItem("SKU999");
    }

    // --- CalculateTotal Tests ---

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        var total = _cart.CalculateTotal();
        Assert.AreEqual(0m, total);
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsPriceTimesQuantity()
    {
        _cart.AddItem("SKU001", 3, 10.00m);
        var total = _cart.CalculateTotal();
        Assert.AreEqual(30.00m, total);
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfAll()
    {
        _cart.AddItem("SKU001", 2, 10.00m);
        _cart.AddItem("SKU002", 1, 5.50m);
        var total = _cart.CalculateTotal();
        Assert.AreEqual(25.50m, total);
    }

    [TestMethod]
    public void CalculateTotal_AfterRemovingItem_ExcludesRemovedItem()
    {
        _cart.AddItem("SKU001", 2, 10.00m);
        _cart.AddItem("SKU002", 1, 5.00m);
        _cart.RemoveItem("SKU001");
        var total = _cart.CalculateTotal();
        Assert.AreEqual(5.00m, total);
    }

    // --- ApplyCoupon Tests ---

    [TestMethod]
    public void ApplyCoupon_ValidCode_NoException()
    {
        _cart.AddItem("SKU001", 1, 50.00m);
        _cart.ApplyCoupon("SAVE10");
    }

    [TestMethod]
    public void ApplyCoupon_ReducesTotal()
    {
        _cart.AddItem("SKU001", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");
        var total = _cart.CalculateTotal();
        Assert.IsTrue(total < 100.00m, $"Expected total < 100 after coupon, but got {total}");
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsException()
    {
        _cart.AddItem("SKU001", 1, 50.00m);
        Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon("INVALIDCODE"));
    }

    // --- Integration / Edge Cases ---

    [TestMethod]
    public void CalculateTotal_AddRemoveAdd_CorrectTotal()
    {
        _cart.AddItem("SKU001", 1, 20.00m);
        _cart.RemoveItem("SKU001");
        _cart.AddItem("SKU002", 2, 15.00m);
        var total = _cart.CalculateTotal();
        Assert.AreEqual(30.00m, total);
    }

    [TestMethod]
    public void CalculateTotal_CouponOnMultipleItems_AppliesToTotal()
    {
        _cart.AddItem("SKU001", 2, 50.00m);
        _cart.AddItem("SKU002", 1, 25.00m);
        _cart.ApplyCoupon("SAVE10");
        var total = _cart.CalculateTotal();
        // Total before coupon = 125.00; after coupon should be less
        Assert.IsTrue(total < 125.00m);
    }
}

